const { createHmac, timingSafeEqual } = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET is not configured');
const invalid = () => [{ json: { valid: false } }];
const input = $input.first();
const headers = input.json.headers ?? {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'];
if (typeof timestamp !== 'string' || !/^\d{1,12}$/.test(timestamp)) return invalid();
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) return invalid();
if (typeof signature !== 'string' || !/^sha256=[a-fA-F0-9]{64}$/.test(signature)) return invalid();
// rawBody=true stores the original bytes as binary.data. NEVER reserialize json.body.
if (!input.binary?.data) return invalid();
const rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
if (rawBody.length > 16384) return invalid();
const expected = createHmac('sha256', secret).update(timestamp + '.').update(rawBody).digest();
const received = Buffer.from(signature.slice(7), 'hex');
if (received.length !== expected.length || !timingSafeEqual(received, expected)) return invalid();
let body;
try { body = JSON.parse(rawBody.toString('utf8')); } catch { return invalid(); }
if (!body || typeof body !== 'object' || Array.isArray(body)) return invalid();
const bounds = {eventId:160,type:20,loanId:160,status:20,toolName:120,recipientName:120,recipientEmail:320,startDate:10,endDate:10};
for (const [key, max] of Object.entries(bounds)) {
  if (typeof body[key] !== 'string' || !body[key].length || body[key].length > max) return invalid();
}
const statuses = ['requested','approved','declined','returned','cancelled'];
if (!statuses.includes(body.type) || body.status !== body.type) return invalid();
if (!/^\d{4}-\d{2}-\d{2}$/.test(body.startDate) || !/^\d{4}-\d{2}-\d{2}$/.test(body.endDate)) return invalid();
// Keep only the explicitly allowed fields, never arbitrary upstream data.
const payload = Object.fromEntries(Object.keys(bounds).map((key) => [key, body[key]]));
return [{json:{valid:true,payload}}];

const payload = $input.first().json.payload;
const state = $getWorkflowStaticData('global');
const now = Date.now();
const recent = state.notificationEvents ?? {};
// A small, best-effort replay cache, valid only for successful published runs.
for (const key of Object.keys(recent)) if (now - recent[key] > 600000) delete recent[key];
state.notificationEvents = recent;
const duplicate = Object.hasOwn(recent, 'notify:' + payload.eventId);
return [{json:{...payload,duplicate,subject:'LendLoop: ' + payload.toolName + ' — ' + payload.status,
  message:payload.recipientName + ', the ' + payload.startDate + ' to ' + payload.endDate + ' loan for ' + payload.toolName + ' is now ' + payload.status + '.'}}];

const item = $input.first().json;
if (!item.duplicate) {
  // MOCK ONLY. Replace with your provider and pass eventId as its idempotency key.
  // Contacts/message remain available in this node's input; omit them from logs.
  console.log(JSON.stringify({channel:'mock',eventId:item.eventId,loanId:item.loanId,type:item.type}));
  const state = $getWorkflowStaticData('global');
  state.notificationEvents ??= {};
  state.notificationEvents['notify:' + item.eventId] = Date.now();
}
return [{json:{ok:true,mock:true,eventId:item.eventId,duplicate:item.duplicate}}];
